public class METVendorRebateOffRemittanceCalcTaskService extends METSysOperationTaskService
{

    guid queueId;
    InventSiteId siteId;
    METVendorRebateOffRemittanceCalcTaskContract contract;
    LedgerJournalTable journalTable;
    LedgerJournalName journalName;
    LedgerJournalEngine journalEngine;
    RecordInsertList transInsertList = new RecordInsertList(tableNum(LedgerJournalTrans));

}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{
    super();
    // get the topPickingProcessId from the contract
    contract = dataContract as METVendorRebateOffRemittanceCalcTaskContract;
    queueId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Initiates the taks process
/// </summary>
/// <param name = "_readPast">Should read past values</param>
protected void processTask(boolean _readPast)
{
    METVendorRebateOffRemittanceCalcStaging transStaging;

    while (this.getDataFromTopPickingQueue(queueId, _readPast))
    {
        try
        {
            ttsbegin;
            journalTable = this.findOrCreateJournal();
            journalName = LedgerJournalName::find(journalTable.JournalName);

            journalEngine = LedgerJournalEngine::construct(journalName.JournalType);

            AmountCur amt;
            select sum(ChargeAmount) from transStaging
                    where transStaging.ProcessId == queueId
                        && transStaging.SiteId == siteId
                    && transStaging.LineAmount != 0;

            //LedgerJournalTrans transDebit = this.createLedgerJournalTrans(transStaging, DebitCredit::Debit, '');

            if (contract.parmGroupByChargeCode() && contract.parmGroupByDepartment())
            {
                while select sum(ChargeAmount) from transStaging
                    group by ChargeCode, Department, CustomerLedgerDimension
                    where transStaging.ProcessId == queueId
                        && transStaging.SiteId == siteId
                        && transStaging.LineAmount != 0
                {
                    if(abs(transStaging.ChargeAmount) < 1)
                    {
                        continue;
                    }

                    amt += roundUpdec(abs(transStaging.ChargeAmount),2);

                    this.createLedgerJournalTrans(transStaging, DebitCredit::Credit, '');
                }
            }
            else if (contract.parmGroupByChargeCode())
            {
                while select sum(ChargeAmount) from transStaging
                    group by ChargeCode, CustomerLedgerDimension
                    where transStaging.ProcessId == queueId
                        && transStaging.SiteId == siteId
                        && transStaging.LineAmount != 0
                {
                    if(abs(transStaging.ChargeAmount) < 1)
                    {
                        continue;
                    }

                    amt += roundUpdec(abs(transStaging.ChargeAmount),2);

                    this.createLedgerJournalTrans(transStaging, DebitCredit::Credit, '');
                }
            }
            //To avoid penny difference between debit and credit entries, we sum the amount on credits and update that back to debit transaction. 
            transDebit.AmountCurDebit = amt;
            transInsertList.add(transDebit);

            transInsertList.insertDatabase();
            this.postJournal(journalTable);

            ttscommit;
        }
        catch
        {
            continue;
        }
    }
}

/// <summary>
/// Clean-up zero value lines if exists
/// </summary>
/// <param name = "_journalTable"><t>LedgerJournalTrans</t> table buffer</param>
private void prePostCleanUp(LedgerJournalTable _journalTable)
{
    LedgerJournalTrans transDel;

    ttsbegin;
    delete_from transDel
        where transDel.JournalNum == _journalTable.JournalNum
        && transDel.AmountCurCredit == 0
        && transDel.AmountCurDebit == 0;
    ttscommit;
}

/// <summary>
/// Once the rebate journal is created, validate and post the same.
/// </summary>
/// <param name = "_journalTable"><t>LedgerJournalTable</t> record buffer</param>
private void postJournal(LedgerJournalTable _journalTable)
{
    METVendorRebateOffRemittanceCalcStaging transStaging;
    try
    {
        //Clean-up 0 value lines
        this.prePostCleanUp(_journalTable);

        LedgerJournalCheckPost::newLedgerJournalTable(journalTable, NoYes::Yes).run();

        VendPackingSlipTrans packingSlipTrans;
        JournalId journalId = _journalTable.JournalNum;
        packingslipTrans.skipAosValidation(true);
        packingslipTrans.skipDataMethods(true);
        packingslipTrans.skipDataSourceValidateWrite(true);

        update_recordset packingslipTrans
            setting METRemittanceJournalId = journalId
        exists join transStaging
            where transStaging.PackingSlipTransRecId == packingSlipTrans.recid
            && transStaging.SiteId == siteId
            && transStaging.ProcessId == queueId;
    }
    catch
    {
        ttsbegin;
        _journalTable.reread();
        _journalTable.selectForUpdate(true);
        _journalTable.delete();
        ttscommit;
    }
    finally
    {
        ttsbegin;

        delete_from transStaging
            where transStaging.SiteId == siteId
                && transStaging.ProcessId == queueId;

        ttscommit;
    }
}

/// <summary>
/// Creates <t>LedgerJournalTrans</t> records
/// </summary>
/// <param name = "_transStaging">Staging record buffer</param>
/// <param name = "_debitCredit">Debit or credit entry</param>
/// <param name = "_voucher">Voucher number to use</param>
/// <returns><t>LedgerJournalTrans</t> table buffer</returns>
private LedgerJournalTrans createLedgerJournalTrans(METVendorRebateOffRemittanceCalcStaging _transStaging, DebitCredit _debitCredit, Voucher _voucher)
{
    LedgerJournalTrans trans;
    trans.clear();
    trans.initValue();

    if (journalEngine)
    {
        journalEngine.ledgerJournalTable(LedgerJournalTable::find(journalTable.journalNum));

        if(_voucher != '')
        {
            trans.Voucher = _voucher;
        }

        journalEngine.initValue(trans);
    }

    MainAccountRecId mainAccountRecId = LedgerDimensionFacade::getMainAccountRecIdFromLedgerDimension(journalName.OffsetLedgerDimension);
    if(_debitCredit == DebitCredit::Debit)
    {
        trans.Txt =strFmt('@SYS76785', siteId, MainAccount::find(mainAccountRecId).Name);
    }
    else
    {
        if(_transStaging.Department)
        {
            trans.Txt = strFmt('@EnterpriseAssetManagementAppSuite:EntAssetForecastUpdateCalc_InfoLogPrefix_Format', siteId, _transStaging.ChargeCode, _transStaging.Department);
        }
        else
        {
            trans.Txt = strFmt('@SYS76785', siteId, _transStaging.ChargeCode);
        }
    }

    trans.TransDate = contract.parmAsOnDate();
    trans.AccountType = LedgerJournalACType::Ledger;

    if(_debitCredit == DebitCredit::Debit)
    {
        trans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(journalName.OffsetLedgerDimension, journalName.DefaultDimension);
        trans.AmountCurDebit = roundUpdec(abs(_transStaging.ChargeAmount),2);
    }
    else
    {
        trans.LedgerDimension = LedgerDimensionFacade::serviceCreateLedgerDimension(_transStaging.CustomerLedgerDimension, journalName.DefaultDimension);
        trans.AmountCurCredit = roundUpdec(abs(_transStaging.ChargeAmount),2);
    }

    journalEngine.initDefaultDimension(trans);
    trans.modifiedField(fieldNum(LedgerJournalTrans, LedgerDimension));
    journalEngine.accountModified(trans);

    trans.JournalNum = journalTable.JournalNum;


    trans.ReverseDate = journalTable.ReverseDate;
    trans.ReverseEntry = journalTable.ReverseEntry;

    if (trans.validateWrite() && _debitCredit == DebitCredit::Credit)
    {
        transInsertList.add(trans);
    }

    return trans;
}

/// <summary>
/// Construct and return journal description
/// </summary>
/// <param name = "_date">Transaction date</param>
/// <returns>Journal description to use on <t>LedgerJournalTable</t></returns>
private str getJournalDescription(TransDate _date)
{
    return strFmt('@MET:RebAccrJournalDesc', mthName(mthOfYr(_date)), year(_date));
}

/// <summary>
/// Find or create a <t>LedgerJournalTable</t> table buffer.
/// </summary>
/// <returns><t>LedgerJournalTable</t> table buffer matching the condition</returns>
private LedgerJournalTable findOrCreateJournal()
{
    LedgerJournalTable journalTableLoc;

    select firstonly journalTableLoc
        where journalTableLoc.METSiteId == siteId
        && journalTableLoc.METAsOfDate == contract.parmAsOnDate()
        && !journalTableLoc.Posted;

    if (!journalTableLoc)
    {
        journalTableLoc.clear();

        journalTableLoc.JournalName = METVendParameters::find().RebateAccrualJournalName;
        journalTableLoc.initFromLedgerJournalName();

        journalTableLoc.METSiteId = siteId;
        journalTableLoc.METAsOfDate = contract.parmAsOnDate();
        journalTableLoc.ReverseDate = contract.parmReversalDate();
        journalTableLoc.ReverseEntry = NoYes::Yes;
        journalTableLoc.insert();

        journalTableLoc.Name = this.getJournalDescription(contract.parmAsOnDate());
        journalTableLoc.ReverseEntry = NoYes::Yes;
        journalTableLoc.update();
    }

    return journalTableLoc;
}

/// <summary>
/// Initializes the process
/// </summary>
/// <param name = "_dataContract"><c>METVendorRebateOffRemittanceCalcTaskContract</c> contract class instance</param>
public void process(METVendorRebateOffRemittanceCalcTaskContract _dataContract)
{
    this.processInternal(_dataContract);
}

/// <summary>
/// Gets data to reserve event orders.
///</summary>
/// <param name = "_processId">Guid created and added in the contract <c>METReserveEventOrdersContract</c>.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METVendorRebateSiteJournalStaging topPickingQueue;
    int                        backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            siteId = topPickingQueue.SiteId;

            topPickingQueue.delete();
        }
        else
        {
            siteId = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (siteId != '');
}
